import { z } from "zod";

/**
 * Public, immutable build-time configuration for a desktop preview installer.
 *
 * One validated manifest is generated by the preview provisioning job, handed
 * to the build as `POSTHOG_DESKTOP_PREVIEW_CONFIG`, and inlined into the
 * Electron main and renderer bundles. It carries only public data: the backend
 * origin, the LLM gateway base URL, the OAuth client id, and the PR identity.
 *
 * A build is a preview build if and only if a valid manifest was supplied.
 */

export const DESKTOP_PREVIEW_SCHEMA_VERSION = 1;

function isCredentialFreeHttpsUrl(value: string, allowPath: boolean): boolean {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return false;
  }
  return (
    url.protocol === "https:" &&
    !url.username &&
    !url.password &&
    (allowPath || url.pathname === "/") &&
    !url.search &&
    !url.hash
  );
}

const httpsOrigin = z
  .string()
  .url()
  .refine(
    (value) => isCredentialFreeHttpsUrl(value, false),
    "backendOrigin must be a credential-free HTTPS origin",
  )
  .transform((value) => new URL(value).origin);

const httpsBaseUrl = z
  .string()
  .url()
  .refine(
    (value) => isCredentialFreeHttpsUrl(value, true),
    "gatewayBaseUrl must be a credential-free HTTPS URL",
  )
  .transform((value) => value.replace(/\/+$/, ""));

const commitSha = z
  .string()
  .regex(/^[0-9a-f]{40}$/, "commitSha must be a full 40-character hex SHA");

const prNumber = z
  .number()
  .int()
  .positive()
  .max(2_147_483_647, "prNumber must be a GitHub PR number");

export const desktopPreviewManifestSchema = z
  .object({
    schemaVersion: z.literal(DESKTOP_PREVIEW_SCHEMA_VERSION),
    kind: z.literal("desktop-preview"),
    repository: z.string().trim().min(1),
    prNumber,
    commitSha,
    backendOrigin: httpsOrigin,
    gatewayBaseUrl: httpsBaseUrl.nullable(),
    oauthClientId: z.string().trim().min(16).max(2048),
  })
  .strict();

export type DesktopPreviewManifest = z.infer<
  typeof desktopPreviewManifestSchema
>;

export class DesktopPreviewConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "DesktopPreviewConfigError";
  }
}

/**
 * Parse and validate a preview manifest. Every failure mode throws
 * `DesktopPreviewConfigError`, so a caller can never fall back to a
 * partially-valid deployment.
 */
export function parseDesktopPreviewManifest(
  raw: unknown,
): DesktopPreviewManifest {
  const result = desktopPreviewManifestSchema.safeParse(raw);
  if (!result.success) {
    const issues = result.error.issues
      .map((issue) => `${issue.path.join(".") || "(root)"}: ${issue.message}`)
      .join("; ");
    throw new DesktopPreviewConfigError(
      `Invalid desktop preview configuration: ${issues}`,
    );
  }
  return result.data;
}

let registeredDeployment: DesktopPreviewManifest | null = null;

/**
 * Make the build's preview deployment available to the `"preview"` region.
 * Each process (Electron main, renderer) registers the inlined manifest once
 * at startup, before any region resolves a URL or client id.
 */
export function registerPreviewDeployment(
  manifest: DesktopPreviewManifest | null,
): void {
  registeredDeployment = manifest;
}

export function getPreviewDeployment(): DesktopPreviewManifest | null {
  return registeredDeployment;
}

export function requirePreviewDeployment(): DesktopPreviewManifest {
  if (!registeredDeployment) {
    throw new DesktopPreviewConfigError(
      "This build has no preview deployment, so the preview region cannot resolve a backend.",
    );
  }
  return registeredDeployment;
}

/**
 * Application identity derived from the PR number, the single source for
 * every surface that must agree: electron-builder metadata, the URL scheme,
 * and the user-data directory. Never derived from manifest-supplied strings,
 * so PR-authored JSON cannot pick a bundle id or a callback scheme. The OAuth
 * redirect URI is `<slug>://callback`; the hogbox desktop profile seeds it.
 */
export interface DesktopPreviewIdentity {
  productName: string;
  appId: string;
  /** URL scheme, user-data directory, Linux package and desktop-file name. */
  slug: string;
  /** Executable name and artifact file prefix. */
  fileName: string;
}

export function desktopPreviewIdentity(
  manifest: DesktopPreviewManifest,
): DesktopPreviewIdentity {
  const pr = manifest.prNumber;
  return {
    productName: `PostHog Preview PR ${pr}`,
    appId: `com.posthog.array.preview.pr${pr}`,
    slug: `posthog-code-preview-pr-${pr}`,
    fileName: `PostHog-Preview-PR-${pr}`,
  };
}
